def load() -> pd.DataFrame:
    import pandas as pd
    path='data/biomedical/input/1-s2.0-S0092867420301070-mmc1.xlsx'
    xls=pd.ExcelFile(path)
    rows=[]
    for sheet in xls.sheet_names:
        df=pd.read_excel(path, sheet_name=sheet)
        cols=list(df.columns)
        rows.append({
            'sheet': sheet,
            'nrows': df.shape[0],
            'ncols': df.shape[1],
            'columns': cols[:40]
        })
    return pd.DataFrame(rows)
